    21   /* This is not an ERR message, the connection is not closed afterwards */
    22  static UA_StatusCode
    23  sendServiceFault(UA_SecureChannel *channel, const UA_ByteString *msg,
    24                   size_t offset, const UA_DataType *responseType,
    25                   UA_UInt32 requestId, UA_StatusCode error) {
    26      UA_RequestHeader requestHeader;
    27      UA_StatusCode retval = UA_RequestHeader_decodeBinary(msg, &offset, &requestHeader);
    28      if(retval != UA_STATUSCODE_GOOD)
    29          return retval;
    30      void *response = UA_alloca(responseType->memSize);
    31      UA_init(response, responseType);
    32      UA_ResponseHeader *responseHeader = (UA_ResponseHeader*)response;
    33      responseHeader->requestHandle = requestHeader.requestHandle;
    34      responseHeader->timestamp = UA_DateTime_now();
    35      responseHeader->serviceResult = error;
    36
    37      // Send error message. Message type is MSG and not ERR, since we are on a securechanenl!
    38      retval = UA_SecureChannel_sendSymmetricMessage(channel, requestId, UA_MESSAGETYPE_MSG,
    39                                                     response, responseType);
    40      UA_RequestHeader_deleteMembers(&requestHeader);
    41      return retval;
    42  }
